def find_longest_repeating_subseq(str):
    """Write a function to count the longest repeating subsequences such that the two subsequences don’t have same string characters at same positions."""
    n = len(str)
    # Dynamic programming for the string against itself: match
    # str[i - 1] with str[j - 1] only when i != j, so matched
    # characters always come from different positions. The table
    # naturally yields zero for empty and single-character inputs.
    prev = [0] * (n + 1)
    for i in range(1, n + 1):
        cur = [0] * (n + 1)
        char_i = str[i - 1]
        for j in range(1, n + 1):
            if char_i == str[j - 1] and i != j:
                cur[j] = prev[j - 1] + 1
            elif prev[j] >= cur[j - 1]:
                cur[j] = prev[j]
            else:
                cur[j] = cur[j - 1]
        prev = cur
    return prev[n]
